from taf.converters.base import FilePatternFinder, OutputFileMapper, NToNConverterObject
from taf.collectors.core.util.string_formatting import partial_format
from taf.collectors.core.entities.local_executor import LocalExecutor
from taf.collectors.core.factories.factory import Factory


class PcapToPdmlFactory(Factory):

    def create(self, configuration, existing_arguments):
        """
        Create a converter for pcap to PDML conversion

        :param configuration: Configuration information of converters
        :param existing_arguments: existing arguments for the final constructor call, that don't need to be created
            (dict with constructor parameter name as key and argument value as value)
        :return: NToNConverterObject
        """
        resulting_arguments = {}
        self._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        return NToNConverterObject(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        """
        Builds the arguments for the constructor call

        :param configuration: Configuration information of converters
        :param dict existing_arguments:
            existing arguments for the final constructor call, that don't need to be created
            (dict with constructor parameter name as key and argument value as value)
        :param dict resulting_arguments:
            resulting arguments for the final constructor call
            (dict with constructor parameter name as key and argument value as value)
        """
        super(PcapToPdmlFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        file_path_pattern = configuration.get("file_path_pattern")
        command_template = configuration.get("command_template")
        tshark_path = configuration.get("tshark_path")
        luashark_path = configuration.get("luashark_path")
        output_extension = ".pdml"
        resulting_arguments["executor"] = self._create_local_executor()
        resulting_arguments["finder"] = self._create_finder(file_path_pattern)
        resulting_arguments["mapper"] = OutputFileMapper(output_extension)
        if tshark_path is None:
            tshark_path = "tshark"
        if luashark_path is None:
            luashark_path = "/opt/luashark/luashark.lua"
        if command_template is None:
            command_template = partial_format("if '{tshark_path}' -G plugins | egrep -iq mcshark ;"
                                              " then lua=() ; else lua=(-X lua_script:'{luashark_path}') ; fi ;"
                                              "'{tshark_path}' -r '{input_file}' \"${{{{lua[@]}}}}\" -T pdml"
                                              " > '{output_file}'",
                                              tshark_path=tshark_path, luashark_path=luashark_path)
        else:
            command_template = partial_format(command_template, tshark_path=tshark_path, luashark_path=luashark_path)
        resulting_arguments["command_template"] = command_template

    def _create_finder(self, file_path_pattern):
        return FilePatternFinder(file_path_pattern)

    def _create_local_executor(self):
        return LocalExecutor()
